import sqlite3, math, copy
from collections import defaultdict

DB='/app/manufacturing.db'
conn=sqlite3.connect(DB)
conn.row_factory=sqlite3.Row
cur=conn.cursor()

parts={}
cur.execute('SELECT * FROM parts')
for r in cur.fetchall():
    d=dict(r); parts[d['part_id']]=dict(d)

bom=defaultdict(list)
cur.execute('SELECT * FROM bom')
for r in cur.fetchall():
    d=dict(r); bom[d['parent_part_id']].append(d)

workcenters={}
cur.execute('SELECT * FROM workcenters')
for r in cur.fetchall():
    d=dict(r); workcenters[d['workcenter_id']]=float(d['available_hours'])

routing=defaultdict(list)
cur.execute('SELECT * FROM routing')
for r in cur.fetchall():
    d=dict(r); routing[d['parent_part_id']].append(d)

subs=defaultdict(list)
cur.execute('SELECT * FROM substitutes ORDER BY primary_part_id,preference_rank,substitute_part_id')
for r in cur.fetchall():
    d=dict(r); subs[d['primary_part_id']].append(d)

orders=[]
cur.execute('SELECT * FROM orders ORDER BY priority ASC, order_id DESC')
for r in cur.fetchall():
    d=dict(r); orders.append(d)
conn.close()

# topological order parent-before-child
indeg={p:0 for p in parts}
graph=defaultdict(set)
for p, edges in bom.items():
    for e in edges:
        child=e['child_part_id']
        graph[p].add(child)
for p in parts:
    for c in graph.get(p,[]):
        indeg[c]+=1
queue=sorted([p for p in parts if indeg[p]==0])
topo=[]
while queue:
    p=queue.pop(0)
    topo.append(p)
    for c in sorted(graph.get(p,[])):
        indeg[c]-=1
        if indeg[c]==0:
            queue.append(c)
            queue.sort()
print('topo len',len(topo), 'parts',len(parts))
print('topo first 15', topo[:15])

def simulate_build(product, target, init_inv, init_wc):
    inv=dict(init_inv)
    wc=dict(init_wc)
    demands=defaultdict(int)
    demands[product]=target
    for p in topo:
        qty=demands.get(p,0)
        if qty<=0:
            continue
        demands[p]=0
        avail=inv[p]
        consume=min(qty,avail)
        inv[p]=avail-consume
        rem=qty-consume
        if rem<=0:
            continue
        if p in bom:
            batch=parts[p]['batch_size']
            build_qty=math.ceil(rem/batch - 1e-12)*batch
            # routing
            for rt in routing[p]:
                wid=rt['workcenter_id']
                hrs=rt['setup_hours'] + build_qty*rt['run_hours_per_unit']
                if hrs > wc[wid] + 1e-9:
                    return None
                wc[wid] -= hrs
            # child reqs
            for b in bom[p]:
                child=b['child_part_id']
                base=b['qty_per']*build_qty
                adj=math.ceil(base*(1.0 + b['scrap_rate_pct']/100.0) - 1e-12) + b['setup_scrap_qty']
                demands[child] += adj
            if build_qty > rem:
                inv[p] += build_qty - rem
        else:
            for s in subs.get(p,[]):
                sub_id=s['substitute_part_id']
                ratio=s['qty_ratio']
                if ratio <= 0:
                    continue
                cover=int(inv[sub_id] // ratio) if inv[sub_id] >= 0 else 0
                take=min(rem,cover)
                if take<=0:
                    continue
                inv[sub_id] -= take*ratio
                rem -= take
                if rem<=0:
                    break
            if rem > 1e-12:
                return None
    for p in topo:
        if demands[p] > 1e-12:
            return None
    return (inv,wc)

current_inv={p: float(parts[p]['on_hand_qty']) for p in parts}
current_wc=dict(workcenters)
for order in orders:
    product=order['product_part_id']
    req=order['requested_qty']
    batch=parts[product]['batch_size']
    max_k=req//batch
    init_inv, init_wc=dict(current_inv), dict(current_wc)
    allocated=0; res_inv=init_inv; res_wc=init_wc
    if req>0 and batch>0:
        for k in range(max_k, -1, -1):
            target=k*batch
            if target==0:
                allocated=0; res_inv=dict(init_inv); res_wc=dict(init_wc); break
            out=simulate_build(product, target, init_inv, init_wc)
            if out is not None:
                allocated=target
                res_inv,res_wc=out
                break
    short=req-allocated
    print(f'{order["order_id"]:8s} prod={product:4s} req={req:3d} batch={batch} alloc={allocated:3d} short={short:3d}')
    current_inv=res_inv
    current_wc=res_wc
print('\nFinal workcenter hours:')
for w in sorted(current_wc): print(w,current_wc[w])
print('\nFinal inventory nonzero/negative:')
for p in sorted(current_inv):
    if current_inv[p] != 0:
        print(p, current_inv[p])
